mapper.sql:
FROM products p JOIN categories c ON c.id = p.category_id

  p.status = 'ACTIVE'

    AND (p.name LIKE CONCAT('%', #{c.q}, '%')
      OR p.brand LIKE CONCAT('%', #{c.q}, '%')
      OR p.description LIKE CONCAT('%', #{c.q}, '%'))


    AND p.category_id IN
    #{cid}


    AND p.brand IN
    #{b}

  AND p.price >= #{c.minPrice}
  AND p.price <= #{c.maxPrice}
  AND p.rating >= #{c.minRating}

mapper.update:
UPDATE products
SET category_id = #{categoryId}, sku = #{sku}, name = #{name}, slug = #{slug},
    description = #{description}, brand = #{brand}, price = #{price}, status = #{status}
WHERE id = #{id}

mapper.select:
SELECT , p.source_id
FROM products p JOIN categories c ON c.id = p.category_id
WHERE p.id = #{id}
